<?php
namespace App\Http\Requests\Tenant\Ticket; use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Rule;
class TicketRequest extends FormRequest { public function authorize():bool{return (bool)$this->user('tenant')?->can($this->isMethod('post')?'tickets.create':'tickets.update');} public function rules():array{return ['subject'=>['required','string','max:500'],'description'=>['nullable','string','max:100000'],'contact_id'=>['required','exists:contacts,id'],'company_id'=>['nullable','exists:companies,id'],'conversation_id'=>['nullable','exists:conversations,id'],'channel_id'=>['nullable','exists:channels,id'],'team_id'=>['nullable','exists:teams,id'],'assignee_id'=>['nullable','exists:users,id'],'priority'=>['required',Rule::in(['low','normal','high','urgent'])],'status_id'=>['required','exists:ticket_statuses,id'],'category_id'=>['nullable','exists:ticket_categories,id'],'source'=>['nullable','in:manual,email,web_chat,api,portal'],'tag_ids'=>['nullable','array'],'tag_ids.*'=>['integer','exists:tags,id'],'custom_fields'=>['nullable','array']];} }
